import { Component, Injectable, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar } from '@angular/material/snack-bar';

/** How long a toast stays visible, in milliseconds (section 3.2). */
const TOAST_DURATION_MS = 4000;

export interface ToastData {
  message: string;
}

/** The content of a toast; its host element carries the `toast` identifier (section 9.6). */
@Component({
  selector: 'app-toast',
  template: '{{ data.message }}',
  host: { 'data-testid': 'toast' },
})
export class ToastMessage {
  readonly data = inject<ToastData>(MAT_SNACK_BAR_DATA);
}

/** Shows short messages as toasts. Opening a toast replaces the one that is visible. */
@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastMessage, {
      data: { message } satisfies ToastData,
      duration: TOAST_DURATION_MS,
    });
  }
}

import { Component, computed, effect, inject, linkedSignal, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../api.service';
import { formatShowDate, parseIsoDate } from '../dates';
import { Movie, Screening } from '../models';
import { ToastService } from '../toast/toast';

type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

interface SeatView {
  column: number;
  /** Seat identifiers the seat occupies: one. */
  ids: string[];
  state: SeatState;
  gridColumn: string;
}

interface CouchView {
  start: number;
  end: number;
  /** Seat identifiers the couch occupies: two. */
  ids: string[];
  state: SeatState;
  gridColumn: string;
}

interface AisleView {
  gridColumn: string;
}

interface RowView {
  number: number;
  seats: SeatView[];
  couches: CouchView[];
  aisles: AisleView[];
}

interface SelectionLine {
  row: number;
  /** Seats of the row in column order, e.g. "11, 12" or "1-2". */
  seats: string;
}

interface LegendItem {
  state: SeatState;
  label: string;
}

const ROW_COUNT = 15;
const COLUMN_COUNT = 24;
const COUCH_ROW = 15;
/** Rows 1 to this number have no seats in columns 1–4 (the entrance). */
const ENTRANCE_LAST_ROW = 10;
/** Aisles sit after these columns; each is two grid tracks wide. */
const AISLE_AFTER_COLUMNS = [4, 20];
/** Grid tracks of the row labels; the seat columns occupy the tracks in between. */
const LEFT_LABEL_TRACK = 1;
const RIGHT_LABEL_TRACK = 30;
/** A booking holds at most this many seats; a couch counts as two. */
const MAX_SEATS = 10;

const LEGEND: LegendItem[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

/**
 * Grid track of a seat column. Track 1 is the left row label, tracks 2–29 hold the seat
 * columns with each aisle taking two tracks, track 30 is the right row label.
 */
function gridTrack(column: number): number {
  return 1 + column + (column > 4 ? 2 : 0) + (column > 20 ? 2 : 0);
}

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

/**
 * State of a seat or couch made of `ids`. Unavailable wins over selected; a couch is
 * selected only when both of its seats are, so it is never half-selected.
 */
function stateOf(
  ids: readonly string[],
  accessible: boolean,
  occupied: ReadonlySet<string>,
  selected: ReadonlySet<string>,
): SeatState {
  if (ids.some((id) => occupied.has(id))) {
    return 'unavailable';
  }
  if (ids.every((id) => selected.has(id))) {
    return 'selected';
  }
  return accessible ? 'accessible' : 'available';
}

function buildRows(occupied: ReadonlySet<string>, selected: ReadonlySet<string>): RowView[] {
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const number = index + 1;
    const seats: SeatView[] = [];
    const couches: CouchView[] = [];

    if (number === COUCH_ROW) {
      for (let start = 1; start < COLUMN_COUNT; start += 2) {
        const end = start + 1;
        const ids = [seatId(number, start), seatId(number, end)];
        couches.push({
          start,
          end,
          ids,
          state: stateOf(ids, false, occupied, selected),
          gridColumn: `${gridTrack(start)} / span 2`,
        });
      }
    } else {
      const firstColumn = number <= ENTRANCE_LAST_ROW ? 5 : 1;
      for (let column = firstColumn; column <= COLUMN_COUNT; column++) {
        const ids = [seatId(number, column)];
        seats.push({
          column,
          ids,
          state: stateOf(ids, isAccessible(number, column), occupied, selected),
          gridColumn: String(gridTrack(column)),
        });
      }
    }

    const aisles = AISLE_AFTER_COLUMNS.map((column) => ({
      gridColumn: `${gridTrack(column) + 1} / span 2`,
    }));

    return { number, seats, couches, aisles };
  });
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toasts = inject(ToastService);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });

  /** The screening id from the URL; undefined keeps the resource idle. */
  private readonly screeningId = computed(() => this.params().get('id') ?? undefined);

  readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }): Promise<{ screening: Screening; movie: Movie }> => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      return { screening, movie };
    },
  });

  readonly screening = computed(() => (this.data.hasValue() ? this.data.value().screening : null));

  readonly showDate = computed(() => {
    const screening = this.screening();
    const date = screening ? parseIsoDate(screening.date) : null;
    return screening && date ? formatShowDate(date, screening.time) : '';
  });

  private readonly occupied = computed<ReadonlySet<string>>(
    () => new Set(this.screening()?.occupiedSeats ?? []),
  );

  /** Identifiers of the selected seats; a couch contributes both of its identifiers. Starts empty for each screening. */
  readonly selectedIds = linkedSignal<string | undefined, ReadonlySet<string>>({
    source: this.screeningId,
    computation: () => new Set<string>(),
  });

  readonly selectedCount = computed(() => this.selectedIds().size);

  readonly rows = computed<RowView[]>(() =>
    this.screening() ? buildRows(this.occupied(), this.selectedIds()) : [],
  );

  /** The selected-seats panel: one line per row with a selection, in row order. */
  readonly selectionLines = computed<SelectionLine[]>(() =>
    this.rows()
      .map((row) => {
        const picked = [
          ...row.seats
            .filter((seat) => seat.state === 'selected')
            .map((seat) => ({ column: seat.column, label: String(seat.column) })),
          ...row.couches
            .filter((couch) => couch.state === 'selected')
            .map((couch) => ({ column: couch.start, label: `${couch.start}-${couch.end}` })),
        ].sort((a, b) => a.column - b.column);
        return { row: row.number, seats: picked.map((item) => item.label).join(', ') };
      })
      .filter((line) => line.seats !== ''),
  );

  readonly legend = LEGEND;
  readonly leftLabelColumn = String(LEFT_LABEL_TRACK);
  readonly rightLabelColumn = String(RIGHT_LABEL_TRACK);

  constructor() {
    effect(() => {
      if (this.data.status() === 'error') {
        void this.router.navigate(['/']);
      }
    });
  }

  /**
   * Selects or deselects the seat or couch made of `ids`. Unavailable seats are ignored; a
   * selection that would exceed the cap is ignored and shows a toast. Deselecting is always allowed.
   */
  toggle(ids: readonly string[]): void {
    const occupied = this.occupied();
    if (ids.some((id) => occupied.has(id))) {
      return;
    }

    const selected = new Set(this.selectedIds());
    if (ids.every((id) => selected.has(id))) {
      ids.forEach((id) => selected.delete(id));
    } else {
      const added = ids.filter((id) => !selected.has(id)).length;
      if (selected.size + added > MAX_SEATS) {
        this.toasts.show(`Maximum ${MAX_SEATS} seats per booking`);
        return;
      }
      ids.forEach((id) => selected.add(id));
    }
    this.selectedIds.set(selected);
  }

  cancel(): void {
    void this.router.navigate(['/']);
  }

  continueToSummary(): void {
    const screening = this.screening();
    if (!screening || this.selectedCount() === 0) {
      return;
    }
    void this.router.navigate(['/screenings', screening.id, 'summary']);
  }
}
@if (screening()) {
<header class="heading">
  <h1 data-testid="seat-map-title">Choose your seats</h1>
  <p data-testid="seat-map-subtitle">Show Date: {{ showDate() }}</p>
</header>

<section class="auditorium">
  <div class="auditorium-inner">
    <!-- prettier-ignore -->
    <p class="seat-limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>
    <div class="screen" data-testid="screen-indicator">SCREEN</div>

    <div class="seat-map" data-testid="seat-map">
      @for (row of rows(); track row.number) {
      <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.number">
        <span
          class="row-label"
          data-testid="row-label-left"
          [attr.data-row]="row.number"
          [style.grid-column]="leftLabelColumn"
          >{{ row.number }}</span
        >

        @for (aisle of row.aisles; track $index) {
        <span
          class="aisle"
          data-testid="aisle"
          [attr.data-row]="row.number"
          [style.grid-column]="aisle.gridColumn"
        ></span>
        } @for (seat of row.seats; track seat.column) {
        <!-- prettier-ignore -->
        <button
          type="button"
          class="seat"
          data-testid="seat"
          [attr.data-row]="row.number"
          [attr.data-column]="seat.column"
          [attr.data-state]="seat.state"
          [disabled]="seat.state === 'unavailable'"
          [style.grid-column]="seat.gridColumn"
          (click)="toggle(seat.ids)"
        >{{ seat.column }}</button>
        } @for (couch of row.couches; track couch.start) {
        <!-- prettier-ignore -->
        <button
          type="button"
          class="couch"
          data-testid="couch"
          [attr.data-row]="row.number"
          [attr.data-column-start]="couch.start"
          [attr.data-column-end]="couch.end"
          [attr.data-state]="couch.state"
          [disabled]="couch.state === 'unavailable'"
          [style.grid-column]="couch.gridColumn"
          (click)="toggle(couch.ids)"
        >{{ couch.start }}-{{ couch.end }}</button>
        }

        <span
          class="row-label"
          data-testid="row-label-right"
          [attr.data-row]="row.number"
          [style.grid-column]="rightLabelColumn"
          >{{ row.number }}</span
        >
      </div>
      }
    </div>
  </div>
</section>

<section class="legend" data-testid="legend">
  @for (item of legend; track item.state) {
  <div class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
    <span class="swatch swatch-{{ item.state }}"></span>
    <span>{{ item.label }}</span>
  </div>
  }
</section>

<section class="selected-seats" data-testid="selected-seats">
  <p data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</p>
  @for (line of selectionLines(); track line.row) {
  <!-- prettier-ignore -->
  <p data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.seats }}</p>
  }
</section>

<div class="actions">
  <!-- prettier-ignore -->
  <button mat-stroked-button type="button" data-testid="cancel-button" (click)="cancel()">Cancel</button>
  <!-- prettier-ignore -->
  <button
    mat-flat-button
    type="button"
    data-testid="continue-button"
    [disabled]="selectedCount() === 0"
    (click)="continueToSummary()"
  >Continue</button>
</div>
}

import { Component, provideZonelessChangeDetection } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter, Router, RouterOutlet } from '@angular/router';
import { Observable, of, throwError } from 'rxjs';
import { vi } from 'vitest';
import { ApiService } from '../api.service';
import { Movie, Screening } from '../models';
import { MovieList } from '../movie-list/movie-list';
import { SeatSelection } from './seat-selection';

const movie: Movie = {
  id: 1,
  title: 'The Silent Harbor',
  genre: 'Drama',
  runtimeMinutes: 128,
  format: 'PL subtitles',
};

const screening: Screening = {
  id: 1,
  movieId: 1,
  date: '2026-09-15',
  time: '16:00',
  occupiedSeats: ['R3C7', 'R15C5', 'R15C6'],
};

@Component({
  imports: [RouterOutlet],
  template: '<router-outlet />',
})
class Host {}

function createApi() {
  return {
    getScreening: vi.fn((id: string): Observable<Screening> => {
      return id === '1' ? of(screening) : throwError(() => new Error('404'));
    }),
    getMovie: vi.fn((): Observable<Movie> => of(movie)),
    getMovies: vi.fn((): Observable<Movie[]> => of([movie])),
    getScreeningsByDate: vi.fn((): Observable<Screening[]> => of([])),
  };
}

async function settle(fixture: ComponentFixture<Host>): Promise<void> {
  for (let i = 0; i < 6; i++) {
    await new Promise((resolve) => setTimeout(resolve, 0));
    fixture.detectChanges();
  }
}

function queryAll(fixture: ComponentFixture<Host>, testId: string): HTMLElement[] {
  return Array.from(
    (fixture.nativeElement as HTMLElement).querySelectorAll<HTMLElement>(
      `[data-testid="${testId}"]`,
    ),
  );
}

function query(fixture: ComponentFixture<Host>, testId: string): HTMLElement | null {
  return queryAll(fixture, testId)[0] ?? null;
}

async function open(
  url: string,
  api: ReturnType<typeof createApi>,
): Promise<ComponentFixture<Host>> {
  TestBed.configureTestingModule({
    providers: [
      provideZonelessChangeDetection(),
      provideNativeDateAdapter(),
      provideRouter([
        { path: '', component: MovieList },
        { path: 'screenings/:id/seats', component: SeatSelection },
      ]),
      { provide: ApiService, useValue: api },
    ],
  });
  const fixture = TestBed.createComponent(Host);
  fixture.detectChanges();
  await TestBed.inject(Router).navigateByUrl(url);
  await settle(fixture);
  return fixture;
}

describe('SeatSelection', () => {
  it('shows the title, the show date and the seat limit', async () => {
    const fixture = await open('/screenings/1/seats', createApi());

    expect(query(fixture, 'seat-map-title')?.textContent?.trim()).toBe('Choose your seats');
    expect(query(fixture, 'seat-map-subtitle')?.textContent?.trim()).toBe(
      'Show Date: Tuesday 15 Sep 16:00',
    );
    expect(query(fixture, 'seat-limit-info')?.textContent?.trim()).toBe(
      'You can reserve up to 10 seats per reservation',
    );
    expect(query(fixture, 'screen-indicator')?.textContent?.trim()).toBe('SCREEN');
  });

  it('draws 15 rows with row labels on both edges and two aisles each', async () => {
    const fixture = await open('/screenings/1/seats', createApi());

    const rows = queryAll(fixture, 'seat-row');
    expect(rows.map((row) => row.dataset['row'])).toEqual(
      Array.from({ length: 15 }, (_, i) => String(i + 1)),
    );
    expect(queryAll(fixture, 'row-label-left').map((el) => el.textContent?.trim())).toEqual(
      Array.from({ length: 15 }, (_, i) => String(i + 1)),
    );
    expect(queryAll(fixture, 'row-label-right').map((el) => el.textContent?.trim())).toEqual(
      Array.from({ length: 15 }, (_, i) => String(i + 1)),
    );
    expect(queryAll(fixture, 'aisle').length).toBe(30);
    expect(queryAll(fixture, 'aisle').every((el) => el.textContent === '')).toBe(true);
  });

  it('has 308 selectable elements: 200 seats in rows 1-10, 96 in rows 11-14, 12 couches in row 15', async () => {
    const fixture = await open('/screenings/1/seats', createApi());

    const seats = queryAll(fixture, 'seat');
    const couches = queryAll(fixture, 'couch');
    expect(seats.length + couches.length).toBe(308);
    expect(couches.length).toBe(12);
    expect(seats.filter((seat) => Number(seat.dataset['row']) <= 10).length).toBe(200);
    expect(seats.filter((seat) => Number(seat.dataset['row']) >= 11).length).toBe(96);
  });

  it('numbers columns globally, starting at 5 in rows 1-10, and labels each seat with its column', async () => {
    const fixture = await open('/screenings/1/seats', createApi());

    const columnsOf = (row: number) =>
      queryAll(fixture, 'seat')
        .filter((seat) => Number(seat.dataset['row']) === row)
        .map((seat) => Number(seat.dataset['column']));
    expect(columnsOf(1)).toEqual(Array.from({ length: 20 }, (_, i) => i + 5));
    expect(columnsOf(11)).toEqual(Array.from({ length: 24 }, (_, i) => i + 1));
    expect(columnsOf(15)).toEqual([]);

    const seatsRow11 = queryAll(fixture, 'seat').filter((seat) => seat.dataset['row'] === '11');
    expect(seatsRow11.every((seat) => seat.textContent === seat.dataset['column'])).toBe(true);
  });

  it('places seats of the same column at the same grid position in every row', async () => {
    const fixture = await open('/screenings/1/seats', createApi());

    const position = (row: number, column: number) =>
      queryAll(fixture, 'seat').find(
        (seat) => seat.dataset['row'] === String(row) && seat.dataset['column'] === String(column),
      )?.style.gridColumn;
    expect(position(11, 12)).toBe(position(14, 12));
