:host {
  display: block;
  max-width: 1120px;
  margin: 0 auto;
  padding: 24px 16px;
}

.heading {
  margin-bottom: 24px;

  h1 {
    margin: 0 0 8px;
    font-size: 1.75rem;
  }

  p {
    margin: 0;
    opacity: 0.8;
  }
}

.auditorium {
  display: flex;
  justify-content: center;
}

.auditorium-inner {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: max-content;
}

.seat-limit {
  margin: 0;
  text-align: center;
}

.screen {
  padding: 6px 0;
  border-radius: 4px;
  background: #e0e0e0;
  color: #424242;
  font-size: 0.875rem;
  letter-spacing: 0.3em;
  text-align: center;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

// 1 label track, 28 seat tracks (4 seats, aisle, 16 seats, aisle, 4 seats), 1 label track.
.seat-row {
  display: grid;
  grid-template-columns: 24px repeat(28, 32px) 24px;
  column-gap: 4px;
  align-items: center;
}

.row-label {
  font-size: 0.75rem;
  text-align: center;
  opacity: 0.8;
