59	    .sort((a, b) => a.row - b.row || a.column - b.column);
60	
61	  const tickets: Ticket[] = [];
62	  const couches = new Set<number>();
63	  for (const { row, column } of seats) {
64	    if (row === COUCH_ROW) {
65	      // Couches cover columns 1–2, 3–4, … 23–24, so a couch starts at an odd column.
66	      const start = column % 2 === 1 ? column : column - 1;
67	      if (couches.has(start)) {
68	        continue;
69	      }
70	      couches.add(start);
71	      tickets.push({
72	        ids: [seatId(row, start), seatId(row, start + 1)],
73	        row,
74	        seat: `Couch ${start}-${start + 1}`,
75	        price: COUCH_PRICE,
76	      });
77	    } else {
78	      tickets.push({
79	        ids: [seatId(row, column)],
80	        row,
81	        seat: String(column),
82	        price: seatPrice(row),
83	      });
84	    }
85	  }
86	  return tickets;
87	}
