113	  /** The seats of the booking in progress when it belongs to the screening, otherwise none. */
114	  seatsFor(screeningId: string | undefined): string[] {
115	    const booking = this.load();
116	    return booking !== null && booking.screeningId === Number(screeningId) ? booking.seats : [];
